import { subject, columns, values } from '../xl/ttl.js'
import { Query } from '../query.js'

const unwrapped = args => Array.isArray(args[0]) ? args[0] : args

export class XSERT extends Query {
  static entries (...args) { return (new this).entries(...args) }
  static into (x,...tail) {
    if (x.raw) return (new this)._set ('into', subject(x,...tail))  //> INSERT.into`Foo`
    const insert = (new this)._set ('into', subject(x))             //> INSERT.into(Foo)
    return !tail.length ? insert : insert._tail(...tail)            //> INSERT.into(Foo, ...?)
  };  _tail (...tail) {
    if (unwrapped(tail)[0]?.split) return this.columns(...tail)     //> INSERT.into(Foo, columns)
    return this._set ('entries', unwrapped(tail))                   //> INSERT.into(Foo, entries)
  }
  into (...args) { return this._set('into', subject(...args)) }
  entries (...args) { return this._set('entries', unwrapped(args)) }
  columns (...args) { return this._add('columns', columns(...args).map(c => c.ref[0])) }
  values (...args) { return this._set('values', values(...args)) }
  rows (...args) { return this._set('rows', unwrapped(args)) }
  from (...args) { return this._set('from', Query.for(...args)) }
  get subject() { return this._.into }
}

export class INSERT extends XSERT { INSERT = {} }
export class UPSERT extends XSERT { UPSERT = {} }
